#!/bin/bash
# Delete a solver run's bulk visualisation output, keeping everything that is
# read downstream.
#
# An OpenLB run writes ~99% of its bytes as VTK field dumps for ParaView. None
# of it is read by the grading pipeline, which consumes only:
#
#     tmp/ellipse2d*_cp.csv      surface Cp, graded by cp_metrics
#     tmp/ellipse2d*_force.csv   integrated Cd/Cl
#     run.log                    parameters, convergence, failure diagnosis
#
# A single run at RESOLUTION 400 is ~2.5 GB, so a 27-run sweep costs ~60 GB for
# data that is regenerated by re-running the case. Runs are cheap (seconds to
# tens of minutes) and fully scripted, so the fields are not worth storing.
#
# **Refuses to prune an incomplete run.** If the CSVs are absent the run either
# failed or is still going, and its VTK output may be the only diagnostic left.
#
# Usage:
#   prune_run_output.sh <run_dir> [<run_dir> ...]
#   prune_run_output.sh --all          # every complete run under cfd/ and outputs/
set -uo pipefail

ROOT="$(cd "$(dirname "$0")/../.." && pwd)"
BULK=(vtkData imageData gnuplotData introspectionData)

human() { numfmt --to=iec --suffix=B "${1:-0}" 2>/dev/null || echo "${1}B"; }

prune_one() {
  local d="$1"
  [ -d "$d" ] || return 0
  # Complete == the CSVs the grading pipeline reads, OR -- for the stock
  # cylinder2d example, which reports through stdout only -- a run.log carrying
  # the end-of-run timer. Either way the run finished and its fields are
  # regenerable.
  local ok=1
  if ls "$d"/tmp/*_cp.csv >/dev/null 2>&1 && ls "$d"/tmp/*_force.csv >/dev/null 2>&1; then
    ok=0
  elif grep -q "measured time" "$d/run.log" 2>/dev/null; then
    ok=0
  fi
  if [ "$ok" -ne 0 ]; then
    echo "  skip (incomplete, keeping diagnostics): $(basename "$d")"
    return 0
  fi
  local before after
  before=$(du -sb "$d" 2>/dev/null | cut -f1)
  for b in "${BULK[@]}"; do
    rm -rf "${d:?}/tmp/$b"
  done
  after=$(du -sb "$d" 2>/dev/null | cut -f1)
  FREED=$((FREED + before - after))
  echo "  pruned $(basename "$d"): $(human $before) -> $(human $after)"
}

FREED=0

if [ "${1:-}" = "--all" ]; then
  mapfile -t dirs < <(
    find "$ROOT/cfd/ellipse2d/runs" "$ROOT/outputs/paper1" \
      -mindepth 1 -type d -name tmp 2>/dev/null | xargs -r -n1 dirname
  )
  echo "scanning ${#dirs[@]} run directories"
  for d in "${dirs[@]}"; do prune_one "$d"; done
else
  [ $# -gt 0 ] || { echo "usage: $0 <run_dir>... | --all"; exit 1; }
  for d in "$@"; do prune_one "$d"; done
fi

echo "reclaimed $(human $FREED)"
